import{_ as a,c as e,o as n,ae as r}from"./chunks/framework.Bi6zybwU.js";const g=JSON.parse('{"title":"How to Use Data Range Picker in Ninja Charts","description":"How to Use Data Range Picker in Ninja Charts","frontmatter":{"title":"How to Use Data Range Picker in Ninja Charts","description":"How to Use Data Range Picker in Ninja Charts"},"headers":[],"relativePath":"guide/ninja-charts/how-to-use-data-range-picker-in-ninja-charts.md","filePath":"guide/ninja-charts/how-to-use-data-range-picker-in-ninja-charts.md"}'),o={name:"guide/ninja-charts/how-to-use-data-range-picker-in-ninja-charts.md"};function i(s,t,c,h,d,l){return n(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="how-to-use-data-range-picker-in-ninja-charts" tabindex="-1">How to Use Data Range Picker in Ninja Charts <a class="header-anchor" href="#how-to-use-data-range-picker-in-ninja-charts" aria-label="Permalink to &quot;How to Use Data Range Picker in Ninja Charts&quot;">​</a></h1><p>Ninja Charts offers multiple chart creation options and chart renderers as well. Once you’re done selecting the chart type and data source, you need to select the <strong>Data Range</strong>. This is where you can edit the data.</p><h2 id="data-range-picker-in-ninja-charts" tabindex="-1">Data Range Picker in Ninja Charts <a class="header-anchor" href="#data-range-picker-in-ninja-charts" aria-label="Permalink to &quot;Data Range Picker in Ninja Charts&quot;">​</a></h2><p>In this step, you can select the data you want on the chart from here. <img src="https://ninjatables.com/wp-content/uploads/2023/02/Ninja-Table-Chart-GIF.gif" alt="Create using Ninja-Charts"></p><ul><li><strong>Select All</strong> columns if you want. You can <strong>Deselect</strong> too.</li><li>The <strong>Number of Items</strong> is set to 10 by default.</li><li>Use <strong>Data Order</strong> to choose the Ascending or Descending order of data.</li><li>Use <strong>Pick Items</strong> if you don’t want all the items in the chart.</li><li>Turn on the <strong>Date Range Picker</strong> if you want to generate the chart by date range. This is how the customization looks. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Column-in-data-source-05-1-scaled.webp" alt=""> Select columns from the left box and move to the right. Or customize from the options from the number of items, date range picker, data order, etc. However, the layout is different for charts created with manual data input. <img src="https://ninjatables.com/wp-content/uploads/2023/10/Add-new-chart.png" alt="Create manual chart"> You can add a new column, add data, or delete/edit data from here. Don’t forget to hit the <strong>Next</strong> button when you’re done here. You’ll be taken to the <strong>Formatting &amp; Preview</strong> tab where you can customize the chart further.</li></ul>',5)])])}const p=a(o,[["render",i]]);export{g as __pageData,p as default};
